(function(){const TABS_SELECTOR='.md-tabs';const TABS_LIST_SELECTOR='.md-tabs__list';const TABS_ITEM_SELECTOR='.md-tabs__item';const TABS_LINK_SELECTOR='.md-tabs__link';const DROPDOWN_SELECTOR='.md-tabs__dropdown';const DROPDOWN_LINK_SELECTOR='.md-tabs__dropdown-link';const DROPDOWN_RIGHT_CLASS='md-tabs__dropdown--right';const DETACHED_CLASS='md-tabs__dropdown--detached';const VISIBLE_CLASS='md-tabs__dropdown--visible';const DROPDOWN_VIEWPORT_GAP=8;const STYLE_ELEMENT_ID='navigation-overlay-styles';function getStyleElement(){let styleElement=document.getElementById(STYLE_ELEMENT_ID);if(!styleElement){styleElement=document.createElement('style');styleElement.id=STYLE_ELEMENT_ID;document.head.appendChild(styleElement);}
return styleElement;}
function initializeNavigationOverlay(){const tabsList=document.querySelector(TABS_LIST_SELECTOR);const tabsContainer=document.querySelector(TABS_SELECTOR);if(!tabsList||!tabsContainer||tabsList.dataset.overlayBound==='true'){return;}
const styleElement=getStyleElement();let isAnimating=false;let currentHoverItem=null;const reattachTimers=new Map();const detachedDropdowns=new Map();tabsList.dataset.overlayBound='true';function getTabItems(){return Array.from(tabsList.querySelectorAll(TABS_ITEM_SELECTOR));}
function alignDropdowns(){const viewportRight=window.innerWidth-DROPDOWN_VIEWPORT_GAP;const listRight=tabsList.getBoundingClientRect().right;getTabItems().forEach((item)=>{const dropdown=item.querySelector(DROPDOWN_SELECTOR);if(!dropdown){return;}
dropdown.classList.remove(DROPDOWN_RIGHT_CLASS);const dropdownRight=dropdown.getBoundingClientRect().right;if(dropdownRight>listRight||dropdownRight>viewportRight){dropdown.classList.add(DROPDOWN_RIGHT_CLASS);}});}
function updateOverlayPosition(targetItem){if(!targetItem){return;}
const rect=targetItem.getBoundingClientRect();const listRect=tabsList.getBoundingClientRect();const left=rect.left-listRect.left;const width=rect.width;styleElement.textContent=`
                .md-tabs__list::before {
                    left: ${left}px !important;
                    width: ${width}px !important;
                }
            `;}
function showOverlay(){tabsList.classList.add('show-hover-overlay');}
var REATTACH_DELAY=200;function hideOverlay(){const itemToReattach=currentHoverItem;if(itemToReattach){const dropdown=getDropdownForItem(itemToReattach);if(dropdown){dropdown.classList.remove(VISIBLE_CLASS);reattachTimers.set(itemToReattach,window.setTimeout(()=>{reattachTimers.delete(itemToReattach);reattachDropdown(itemToReattach);},REATTACH_DELAY));}}
tabsList.classList.remove('show-hover-overlay');isAnimating=false;currentHoverItem=null;}
function reattachAllDetachedDropdowns(){Array.from(detachedDropdowns.keys()).forEach((item)=>{reattachDropdown(item);});}
function getItemIndex(item){return getTabItems().indexOf(item);}
function triggerMoveAnimation(fromItem,toItem){if(isAnimating||!fromItem||!toItem){return;}
const fromIndex=getItemIndex(fromItem);const toIndex=getItemIndex(toItem);isAnimating=true;window.setTimeout(()=>{isAnimating=false;},300);}
function getDropdownForItem(item){if(detachedDropdowns.has(item)){return detachedDropdowns.get(item).dropdown;}
return item.querySelector(DROPDOWN_SELECTOR);}
function detachDropdown(item){if(reattachTimers.has(item)){window.clearTimeout(reattachTimers.get(item));reattachTimers.delete(item);}
if(detachedDropdowns.has(item)){const dropdown=detachedDropdowns.get(item).dropdown;dropdown.classList.add(VISIBLE_CLASS);return dropdown;}
const dropdown=item.querySelector(DROPDOWN_SELECTOR);if(!dropdown){return null;}
const record={dropdown:dropdown,originalParent:dropdown.parentElement,nextSibling:dropdown.nextSibling};detachedDropdowns.set(item,record);dropdown.style.transition='';dropdown.style.opacity='';dropdown.style.visibility='';dropdown.classList.add(DETACHED_CLASS,VISIBLE_CLASS);tabsContainer.appendChild(dropdown);positionDetachedDropdown(item,dropdown);return dropdown;}
function reattachDropdown(item,keepHidden){if(reattachTimers.has(item)){window.clearTimeout(reattachTimers.get(item));reattachTimers.delete(item);}
const record=detachedDropdowns.get(item);if(!record){return;}
const{dropdown,originalParent,nextSibling}=record;dropdown.style.transition='none';dropdown.style.opacity='0';dropdown.style.visibility='hidden';dropdown.classList.remove(DETACHED_CLASS,VISIBLE_CLASS);dropdown.style.position='';dropdown.style.top='';dropdown.style.left='';dropdown.style.right='';if(nextSibling&&nextSibling.parentElement===originalParent){originalParent.insertBefore(dropdown,nextSibling);}else{originalParent.appendChild(dropdown);}
if(keepHidden){detachedDropdowns.delete(item);return;}
window.requestAnimationFrame(()=>{dropdown.style.transition='';dropdown.style.opacity='';dropdown.style.visibility='';});detachedDropdowns.delete(item);}
function positionDetachedDropdown(item,dropdown){const tabsRect=tabsContainer.getBoundingClientRect();const itemRect=item.getBoundingClientRect();dropdown.style.position='absolute';dropdown.style.top=`${itemRect.bottom - tabsRect.top + 3}px`;dropdown.style.left='auto';dropdown.style.right='auto';const dropdownRect=dropdown.getBoundingClientRect();let left=itemRect.left-tabsRect.left;left=Math.max(0,left);const viewportRight=window.innerWidth-DROPDOWN_VIEWPORT_GAP;const maxLeft=viewportRight-tabsRect.left-dropdownRect.width;left=Math.min(left,maxLeft);dropdown.style.left=`${left}px`;dropdown.style.right='auto';}
function updateDetachedDropdownPosition(){if(!currentHoverItem){return;}
const record=detachedDropdowns.get(currentHoverItem);if(record){positionDetachedDropdown(currentHoverItem,record.dropdown);}}
window.requestAnimationFrame(alignDropdowns);if(document.fonts&&document.fonts.ready){document.fonts.ready.then(alignDropdowns);}
getTabItems().forEach((item)=>{item.addEventListener('mouseenter',()=>{const activeItem=tabsList.querySelector('.md-tabs__item--active');const isActive=item===activeItem;if(item!==currentHoverItem){if(currentHoverItem){const oldItem=currentHoverItem;const oldDropdown=getDropdownForItem(oldItem);if(oldDropdown){oldDropdown.classList.remove(VISIBLE_CLASS);reattachTimers.set(oldItem,window.setTimeout(()=>{reattachTimers.delete(oldItem);reattachDropdown(oldItem);},REATTACH_DELAY));}
if(!isActive){triggerMoveAnimation(currentHoverItem,item);}}
currentHoverItem=item;}
detachDropdown(item);if(isActive){return;}
updateOverlayPosition(item);showOverlay();});});document.addEventListener('mouseout',(event)=>{if(!currentHoverItem){return;}
const dropdown=getDropdownForItem(currentHoverItem);const related=event.relatedTarget;const target=event.target;const leftCurrentItem=target===currentHoverItem||currentHoverItem.contains(target);const leftDropdown=dropdown&&(target===dropdown||dropdown.contains(target));if(!leftCurrentItem&&!leftDropdown){return;}
if(related){const relatedItem=related.closest(TABS_ITEM_SELECTOR);if(relatedItem&&tabsList.contains(relatedItem)){return;}}
const enteredCurrentItem=related&&(related===currentHoverItem||currentHoverItem.contains(related));const enteredDropdown=dropdown&&related&&(related===dropdown||dropdown.contains(related));if(enteredCurrentItem||enteredDropdown){return;}
hideOverlay();});tabsList.addEventListener('click',(event)=>{const link=event.target.closest(`${TABS_LINK_SELECTOR}, ${DROPDOWN_LINK_SELECTOR}`);if(!link||!tabsContainer.contains(link)){return;}
if(currentHoverItem){reattachDropdown(currentHoverItem,true);}
hideOverlay();});tabsList.addEventListener('scroll',()=>{window.requestAnimationFrame(updateDetachedDropdownPosition);});let resizeTimeout=null;window.addEventListener('resize',()=>{window.clearTimeout(resizeTimeout);resizeTimeout=window.setTimeout(()=>{hideOverlay();reattachAllDetachedDropdowns();alignDropdowns();},100);});}
function subscribeToPageChanges(callback){if(typeof document$!=='undefined'&&typeof document$.subscribe==='function'){document$.subscribe(()=>{window.requestAnimationFrame(()=>{callback();});});return;}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',callback,{once:true});return;}
callback();}
subscribeToPageChanges(()=>{initializeNavigationOverlay();});})();